interface Slot { value?: number; }
class Present implements Slot { value: number | undefined = 1; }
console.log(`${'value' in new Present()} ${new Present().value}`);

interface Box<T> { value?: T; }
function use<T>(box: Box<T>): void { console.log(box.value); }
use<number>({ value: 1 });

interface Slot { value?: number; }
function reset<T extends Slot>(slot: T): void { slot.value = 1; }
const slot: Slot = {};
reset(slot);
console.log(`${'value' in slot} ${slot.value}`);

function reset(slot: { value?: number }, values: number[]): void { slot.value = 1; }
const slot: { value?: number } = {};
reset(slot, []);
console.log(`${'value' in slot} ${slot.value}`);

interface Slot { value?: number; }
function values(): Slot[] { const result = [{ value: 1 }]; return result; }
for (const slot of values()) console.log(`${'value' in slot} ${slot.value}`);

function value(): number | undefined { return 1; }
const n: number = value();
console.log(n);

function value(): number | undefined { return 1; }
function use(n: number): void { console.log(n); }
use(value());

function use(slot?: { value?: number }): void {
    if (slot) console.log(`${'value' in slot} ${slot.value}`);
}
use({ value: 1 });

interface Host { value?(): number; }
function make(): Host { return { value: () => 1 }; }
console.log(`${'value' in make()} ${make().value}`);

interface Host { value?(): number; }
function reset(host: Host): void { host.value = () => 1; }
const host: Host = {};
reset(host);
console.log(`${'value' in host} ${host.value}`);

interface Slot { value?: number; }
function make(): Slot { return { value: 1 }; }
console.log(`${'value' in make()} ${make().value}`);

function reset(slot: { value?: number }): void { slot.value = 1; }
const slot: { value?: number } = {};
reset(slot);
console.log(`${'value' in slot} ${slot.value}`);
